#!/usr/bin/env bash

set -euo pipefail

# AI: below section was generated by an AI

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_dir="$(cd "$script_dir/../.." && pwd)"
state_root="${TUBES_FLEET_JOB_DIR:-$repo_dir/build_output/fleet-update-jobs}"
wifi_device="${TUBES_WIFI_DEVICE:-}"

usage() {
  cat <<'EOF'
Usage:
  ./fleet_update_job.sh start-one PROFILE SERIAL_DEVICE
  ./fleet_update_job.sh start-target PROFILE SERIAL_DEVICE DEVICE_ID
  ./fleet_update_job.sh start-fleet SERIAL_DEVICE
  ./fleet_update_job.sh status [JOB_ID]
  ./fleet_update_job.sh log [JOB_ID]

start-one updates one physically selected device with upgrade_fast.sh.
start-target updates one release-15-or-newer device from a fresh manifest ID.
start-fleet runs the unattended canary-first fleet updater. Both commands run
under launchd, preserve logs on disk, and restore the previous Wi-Fi network
before recording their final status.
EOF
}

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

find_wifi_device() {
  if [[ -n "$wifi_device" ]]; then
    return
  fi
  wifi_device="$(networksetup -listallhardwareports | awk '
    $0 == "Hardware Port: Wi-Fi" {
      getline
      sub(/^Device: /, "")
      print
      exit
    }
  ')"
  [[ -n "$wifi_device" ]] || fail "could not find the Wi-Fi interface"
}

current_wifi_network() {
  local current
  current="$(networksetup -getairportnetwork "$wifi_device" 2>/dev/null || true)"
  if [[ "$current" == *": "* && "$current" != "You are not associated"* ]]; then
    printf '%s\n' "${current#*: }"
  fi
}

write_status() {
  local job_dir="$1"
  local state="$2"
  local detail="${3:-}"
  local temporary="$job_dir/status.tmp"
  printf 'state=%s\ndetail=%s\nupdated=%s\n' \
    "$state" "$detail" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$temporary"
  mv "$temporary" "$job_dir/status"
}

latest_job_id() {
  [[ -d "$state_root" ]] || return 1
  find "$state_root" -mindepth 1 -maxdepth 1 -type d -exec basename {} \; \
    | LC_ALL=C sort | tail -1
}

resolve_job_dir() {
  local job_id="${1:-}"
  if [[ -z "$job_id" ]]; then
    job_id="$(latest_job_id)" || fail "no fleet update jobs found"
  fi
  [[ "$job_id" =~ ^[0-9]{8}T[0-9]{6}Z-[0-9]+$ ]] || fail "invalid job ID: $job_id"
  [[ -d "$state_root/$job_id" ]] || fail "unknown job ID: $job_id"
  printf '%s\n' "$state_root/$job_id"
}

restore_wifi() {
  local job_dir="$1"
  local original_ssid=""
  if [[ -s "$job_dir/original-ssid" ]]; then
    original_ssid="$(<"$job_dir/original-ssid")"
  fi

  if [[ -n "$original_ssid" ]]; then
    networksetup -setairportnetwork "$wifi_device" "$original_ssid" >/dev/null 2>&1
    return
  fi

  # If macOS could not name the original association, cycling Wi-Fi makes it
  # select a saved preferred network after the temporary update AP disappears.
  networksetup -setairportpower "$wifi_device" off >/dev/null 2>&1 || true
  networksetup -setairportpower "$wifi_device" on >/dev/null 2>&1
}

worker() {
  [[ $# -ge 3 ]] || fail "invalid worker invocation"
  worker_job_dir="$1"
  worker_mode="$2"
  worker_detail="worker-exited-before-updater-completed"
  local serial_device="$3"
  local profile="${4:-}"
  local target_id="${5:-}"
  local update_result=0

  finish_worker() {
    local exit_result=$?
    local restore_result=0
    trap - EXIT INT TERM
    write_status "$worker_job_dir" restoring-network "updater-exit=$exit_result"
    set +e
    restore_wifi "$worker_job_dir"
    restore_result=$?
    set -e
    rm -f "$state_root/active/owner"
    rmdir "$state_root/active" 2>/dev/null || true

    if (( restore_result != 0 )); then
      write_status "$worker_job_dir" failed "network-restore-exit=$restore_result updater-exit=$exit_result"
      exit "$restore_result"
    fi
    if (( exit_result != 0 )); then
      write_status "$worker_job_dir" failed "$worker_detail exit=$exit_result"
      exit "$exit_result"
    fi
    write_status "$worker_job_dir" succeeded "$worker_mode"
    exit 0
  }

  find_wifi_device
  if ! mkdir "$state_root/active" 2>/dev/null; then
    write_status "$worker_job_dir" failed "another fleet update job is active"
    return 1
  fi
  printf '%s\n' "$$" > "$state_root/active/owner"
  trap finish_worker EXIT
  trap 'worker_detail="interrupted"; exit 143' INT TERM
  write_status "$worker_job_dir" running "$worker_mode"
  cd "$repo_dir"

  if [[ "$worker_mode" == "one" ]]; then
    local one_arguments=("$profile" "$serial_device")
    if [[ -n "$target_id" ]]; then
      one_arguments+=(--id "$target_id")
    fi
    if "$script_dir/upgrade_fast.sh" "${one_arguments[@]}"; then
      update_result=0
    else
      update_result=$?
    fi
  else
    if "$script_dir/upgrade_batch.sh" "$serial_device"; then
      update_result=0
    else
      update_result=$?
    fi
  fi
  worker_detail="updater-exit=$update_result"
  return "$update_result"
}

start_job() {
  local mode="$1"
  local profile="$2"
  local serial_device="$3"
  local target_id="${4:-}"
  local job_id job_dir label original_ssid plist_file program_arguments

  command -v launchctl >/dev/null || fail "launchctl is required"
  command -v networksetup >/dev/null || fail "networksetup is required"
  command -v jq >/dev/null || fail "jq is required"
  command -v plutil >/dev/null || fail "plutil is required"
  [[ -c "$serial_device" ]] || fail "serial device is not a character device: $serial_device"
  if [[ "$mode" == "one" ]]; then
    [[ "$profile" =~ ^(dig2go|athom-c3|christmas|golden)$ ]] \
      || fail "unsupported profile: $profile"
  fi
  if [[ -n "$target_id" ]]; then
    local normalized_target="${target_id#0x}"
    normalized_target="${normalized_target#0X}"
    [[ "$normalized_target" =~ ^[0-9A-Fa-f]{4}$ && "$normalized_target" != "0000" ]] \
      || fail "invalid target Device ID: $target_id"
  fi

  find_wifi_device
  mkdir -p "$state_root"
  job_id="$(date -u +%Y%m%dT%H%M%SZ)-$$"
  job_dir="$state_root/$job_id"
  mkdir "$job_dir"
  chmod 700 "$job_dir"
  original_ssid="$(current_wifi_network)"
  printf '%s' "$original_ssid" > "$job_dir/original-ssid"
  printf '%s\n' "$wifi_device" > "$job_dir/wifi-device"
  printf '%s\n' "$mode" > "$job_dir/mode"
  printf '%s\n' "$serial_device" > "$job_dir/serial-device"
  write_status "$job_dir" queued "$mode"

  label="live.rezidence.tubes-fleet-update.${job_id//[^A-Za-z0-9]/-}"
  plist_file="$job_dir/launch-agent.plist"
  program_arguments="$(jq -cn \
    --arg shell /bin/bash \
    --arg script "$script_dir/fleet_update_job.sh" \
    --arg job "$job_dir" \
    --arg mode "$mode" \
    --arg serial "$serial_device" \
    --arg profile "$profile" \
    --arg target "$target_id" \
    '[$shell,$script,"--worker",$job,$mode,$serial,$profile,$target]')"
  plutil -create xml1 "$plist_file"
  plutil -insert Label -string "$label" "$plist_file"
  plutil -insert ProgramArguments -json "$program_arguments" "$plist_file"
  plutil -insert RunAtLoad -bool true "$plist_file"
  plutil -insert KeepAlive -bool false "$plist_file"
  plutil -insert ProcessType -string Background "$plist_file"
  plutil -insert StandardOutPath -string "$job_dir/stdout.log" "$plist_file"
  plutil -insert StandardErrorPath -string "$job_dir/stderr.log" "$plist_file"
  launchctl bootstrap "gui/$(id -u)" "$plist_file"

  echo "JOB_ID=$job_id"
  echo "STATUS=$job_dir/status"
  echo "LOG=$job_dir/stdout.log"
}

show_status() {
  local job_dir
  job_dir="$(resolve_job_dir "${1:-}")"
  echo "JOB_ID=$(basename "$job_dir")"
  cat "$job_dir/status"
}

show_log() {
  local job_dir
  job_dir="$(resolve_job_dir "${1:-}")"
  if [[ -f "$job_dir/stdout.log" ]]; then
    cat "$job_dir/stdout.log"
  fi
  if [[ -s "$job_dir/stderr.log" ]]; then
    echo "--- stderr ---"
    cat "$job_dir/stderr.log"
  fi
}

main() {
  local command="${1:-}"
  case "$command" in
    start-one)
      [[ $# -eq 3 ]] || { usage; return 2; }
      start_job one "$2" "$3" ""
      ;;
    start-target)
      [[ $# -eq 4 ]] || { usage; return 2; }
      start_job one "$2" "$3" "$4"
      ;;
    start-fleet)
      [[ $# -eq 2 ]] || { usage; return 2; }
      start_job fleet "" "$2" ""
      ;;
    status)
      [[ $# -le 2 ]] || { usage; return 2; }
      show_status "${2:-}"
      ;;
    log)
      [[ $# -le 2 ]] || { usage; return 2; }
      show_log "${2:-}"
      ;;
    --worker)
      shift
      worker "$@"
      ;;
    *)
      usage
      return 2
      ;;
  esac
}

main "$@"

# AI: end
